import{_ as s,o as a,c as o,a2 as t}from"./chunks/framework.CuUVYbLV.js";const m=JSON.parse('{"title":"07 让代理记住你（第二教程）","description":"第二个小教程：用记忆库让代理跨会话记住你的决策，并观察它如何被自动注回上下文。","frontmatter":{"title":"07 让代理记住你（第二教程）","description":"第二个小教程：用记忆库让代理跨会话记住你的决策，并观察它如何被自动注回上下文。"},"headers":[],"relativePath":"02-Guide/tutorial/07-memory.md","filePath":"02-Guide/tutorial/07-memory.md"}'),n={name:"02-Guide/tutorial/07-memory.md"};function i(l,e,d,c,p,r){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="_07-让代理记住你-第二教程-memory" tabindex="-1">07 让代理记住你（第二教程）（Memory） <a class="header-anchor" href="#_07-让代理记住你-第二教程-memory" aria-label="Permalink to &quot;07 让代理记住你（第二教程）（Memory）&quot;">​</a></h1><p>本章是一条独立的小教程：让角色把「上次定下的规矩」写进记忆库，再让下一个会话里的它自己想起来。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01 安装并跑通第一个角色</a>（有一个能对话的 <code>code-reviewer</code> 就够了）｜相关：<a href="/rolebox-docs/04-Advanced/memory-system.html">记忆系统</a>、<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a></p></blockquote><h2 id="记忆是什么" tabindex="-1">记忆是什么 <a class="header-anchor" href="#记忆是什么" aria-label="Permalink to &quot;记忆是什么&quot;">​</a></h2><p><strong>记忆（memory，写在项目 <code>.rolebox/</code> 目录下、由 rolebox 在会话启动时回注给角色的持久条目）</strong> 和「会话历史」是两件事：会话是一次性的上下文，记忆是你要它跨会话长期记住的东西。</p><p>三个关键事实：</p><ul><li>记忆库是<strong>每个项目一份</strong>的 SQLite 数据库，落在 <code>&lt;项目&gt;/.rolebox/memory.db</code>；</li><li>角色每次开会话时，rolebox 会把符合条件的记忆摘要拼成 <code>&lt;available_memory&gt;</code> 块注入系统提示——<strong>记忆库为空时这个块根本不出现</strong>；</li><li>「写下来」和「会被自动注入」不是一个门槛：默认只注入相关度 <code>medium</code> 及以上的最近若干条。</li></ul><p>本章继续用 01 章的练习项目 <code>~/rolebox-lab</code>。</p><h2 id="第-1-步-先看记忆库里有什么" tabindex="-1">第 1 步：先看记忆库里有什么 <a class="header-anchor" href="#第-1-步-先看记忆库里有什么" aria-label="Permalink to &quot;第 1 步：先看记忆库里有什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（还没写过任何记忆时）：</span></span>
<span class="line"><span>No memory entries found.</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（空库的形状）：</span></span>
<span class="line"><span>  Memory Store Statistics</span></span>
<span class="line"><span>  ────────────────────────────────────</span></span>
<span class="line"><span>  Total entries:     0</span></span>
<span class="line"><span>  By scope:</span></span>
<span class="line"><span>    (none)</span></span>
<span class="line"><span>  By category:</span></span>
<span class="line"><span>    (none)</span></span>
<span class="line"><span>  By relevance:</span></span>
<span class="line"><span>    (none)</span></span></code></pre></div><p>两条命令回答的问题不同：<code>list</code> 列条目（默认按最近更新排序，最多 20 条），<code>stats</code> 给库的分布——按作用域、按类别、按相关度。定位方式是<strong>工作目录</strong>：CLI 从当前目录向上找到第一个含 <code>.rolebox/</code> 的目录，把它当作项目根，所以在项目的子目录里执行也能命中同一个库。</p><h2 id="第-2-步-把-memory-函数交给角色" tabindex="-1">第 2 步：把 memory 函数交给角色 <a class="header-anchor" href="#第-2-步-把-memory-函数交给角色" aria-label="Permalink to &quot;第 2 步：把 memory 函数交给角色&quot;">​</a></h2><p>记忆的读写由四个工具完成（<code>memory_list</code>、<code>memory_recall</code>、<code>memory_write</code>、<code>memory_update</code>；教程主线用的 opencode 四个都可用），而「回顾会话 → 提炼决策 → 落盘」整套流程封装在内置函数 <code>memory</code> 里。函数要先在 <code>role.yaml</code> 里声明才能激活——函数清单是<strong>合并</strong>语义：<code>plan</code>、<code>execute</code>、<code>loop</code> 三个默认函数始终在，声明只是往清单里加，所以在现有列表末尾追加一行即可（别删掉已经有的函数）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">functions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plan</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">execute</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">memory</span></span></code></pre></div><p>改完重启 harness，让插件重新解析角色（角色在启动时加载）。</p><h2 id="第-3-步-在新会话里触发-memory" tabindex="-1">第 3 步：在新会话里触发 |memory| <a class="header-anchor" href="#第-3-步-在新会话里触发-memory" aria-label="Permalink to &quot;第 3 步：在新会话里触发 |memory|&quot;">​</a></h2><p>新开一个 <code>code-reviewer</code> 会话，在<strong>行首</strong>发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>|memory| 请回顾这个项目的会话，把「错误信息必须包含修复建议」这条约定写进记忆库。</span></span></code></pre></div><p><code>|函数名|</code> 是函数激活语法，必须写在行首。<code>|memory|</code> 默认走增量模式：只处理还没有被记忆归档过的会话；想只扫最近 5 个会话，写成 <code>|memory:recent|</code>。</p><p>应看到角色按内置流程走一遍：先用 <code>memory_list</code> 看已有什么，再用 <code>session_list</code> / <code>session_read</code> 翻会话，写之前用 <code>memory_recall</code> 查重，最后落盘并汇报：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，条数与措辞随你的实际会话不同）：</span></span>
<span class="line"><span>Memory consolidation complete.</span></span>
<span class="line"><span>Processed 1 sessions, wrote 1 new memories, updated 0.</span></span></code></pre></div><h2 id="第-4-步-用命令行验证落盘" tabindex="-1">第 4 步：用命令行验证落盘 <a class="header-anchor" href="#第-4-步-用命令行验证落盘" aria-label="Permalink to &quot;第 4 步：用命令行验证落盘&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 修复建议</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，ID、标题与时间随你的实际决策不同）：</span></span>
<span class="line"><span>  ID           Title                          Category         Relevance  Content</span></span>
<span class="line"><span>  ────────────────────────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  a1b2c3d4e5f6 错误信息必须给出修复建议                   decision         high       错误信息必须包含修复建议…</span></span></code></pre></div><p>再确认库里的形状：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，作用域取决于这条记忆写成了哪种）：</span></span>
<span class="line"><span>  Memory Store Statistics</span></span>
<span class="line"><span>  ────────────────────────────────────</span></span>
<span class="line"><span>  Total entries:     1</span></span>
<span class="line"><span>  By scope:</span></span>
<span class="line"><span>    workspace    1</span></span>
<span class="line"><span>  By category:</span></span>
<span class="line"><span>    decision         1</span></span>
<span class="line"><span>  By relevance:</span></span>
<span class="line"><span>    high       1</span></span></code></pre></div><p><code>rolebox memory list</code> 现在也会列出这一行。要读全文用 <code>rolebox memory show &lt;完整 ID&gt;</code>，删掉用 <code>rolebox memory delete &lt;完整 ID&gt;</code>（<code>delete</code> 会先让你确认，加 <code>-y</code> 跳过）。</p><h2 id="第-5-步-下一个会话-它自己想起来" tabindex="-1">第 5 步：下一个会话，它自己想起来 <a class="header-anchor" href="#第-5-步-下一个会话-它自己想起来" aria-label="Permalink to &quot;第 5 步：下一个会话，它自己想起来&quot;">​</a></h2><p>重启 harness 再开一个会话。这次什么都不用输入——rolebox 已经把记忆摘要拼进了系统提示，形状是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;available_memory&gt;</span></span>
<span class="line"><span>Memory entries from previous sessions. Use memory_recall to search for specific memories.</span></span>
<span class="line"><span>  &lt;memory&gt;</span></span>
<span class="line"><span>    &lt;id&gt;a1b2c3d4e5f6&lt;/id&gt;</span></span>
<span class="line"><span>    &lt;title&gt;错误信息必须给出修复建议&lt;/title&gt;</span></span>
<span class="line"><span>    &lt;category&gt;decision&lt;/category&gt;</span></span>
<span class="line"><span>    &lt;relevance&gt;high&lt;/relevance&gt;</span></span>
<span class="line"><span>    &lt;updated&gt;2026-09-17T08:21:04.512Z&lt;/updated&gt;</span></span>
<span class="line"><span>  &lt;/memory&gt;</span></span>
<span class="line"><span>&lt;/available_memory&gt;</span></span></code></pre></div><p>注入的是<strong>摘要</strong>（ID、标题、类别、相关度、更新时间），不是正文；代理需要细节时会用 <code>memory_recall</code> 检索全文。想亲眼确认，直接在会话里问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我对错误信息的写法有什么约定？</span></span></code></pre></div><p>它应当答出你刚落盘的那条决策，而不是回头问你一遍。</p><p>注入行为可以按角色调整，写在 <code>role.yaml</code> 的 <code>memory:</code> 块里：</p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>作用</th></tr></thead><tbody><tr><td><code>inject</code></td><td><code>true</code></td><td>会话启动时是否注入 <code>&lt;available_memory&gt;</code></td></tr><tr><td><code>max_inject</code></td><td><code>10</code></td><td>最多注入多少条摘要</td></tr><tr><td><code>min_relevance</code></td><td><code>medium</code></td><td>注入的相关度门槛（<code>high</code> / <code>medium</code> / <code>low</code>）</td></tr><tr><td><code>scope</code></td><td><code>both</code></td><td>注入哪些作用域（<code>role</code> / <code>workspace</code> / <code>both</code>）</td></tr></tbody></table><h2 id="第-6-步-workspace-与-role-两种作用域" tabindex="-1">第 6 步：workspace 与 role 两种作用域 <a class="header-anchor" href="#第-6-步-workspace-与-role-两种作用域" aria-label="Permalink to &quot;第 6 步：workspace 与 role 两种作用域&quot;">​</a></h2><p>每条记忆都带一个作用域，它决定的是<strong>归属与过滤</strong>，不是访问权限：</p><table tabindex="0"><thead><tr><th>作用域</th><th>写入时记录的 <code>role_id</code></th><th>适合放什么</th><th>只看它</th></tr></thead><tbody><tr><td><code>workspace</code></td><td><code>shared</code></td><td>项目事实、架构决策、团队约定——所有角色都该知道</td><td><code>rolebox memory list --scope workspace</code></td></tr><tr><td><code>role</code></td><td>写入者的角色 ID</td><td>这个角色自己的工作习惯与内部方法</td><td><code>rolebox memory list --scope role</code></td></tr></tbody></table><p>两点必须说清楚：</p><ol><li><strong>两种作用域存在同一个库里</strong>（<code>&lt;项目&gt;/.rolebox/memory.db</code>），不是两个隔离的数据库。列表、检索、注入都按 <code>scope</code> 过滤，不按 <code>role_id</code> 做访问控制——所以 <code>role</code> 的含义是「归属清晰、可以按作用域挑出来」，而不是「别的角色一定读不到」。要区分它们，看 <code>role_id</code>：<code>workspace</code> 恒为 <code>shared</code>，<code>role</code> 是写入它的角色。</li><li><strong>真正决定「会不会自动出现」的是 <code>memory:</code> 块</strong>，尤其是 <code>scope</code> 与 <code>min_relevance</code>。默认 <code>both</code> + <code>medium</code>：<code>low</code> 相关度的记忆不会被注入，但仍可被 <code>rolebox memory search</code> 或 <code>memory_recall</code> 检索到。</li></ol><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ol><li><strong><code>|memory|</code> 什么也没发生。</strong> 先确认 <code>memory</code> 在 <code>role.yaml</code> 的 <code>functions:</code> 里：不在角色函数清单里的函数名会被解析器吃掉但不激活，看起来只是消息少了前缀。再确认前缀写在<strong>行首</strong>。</li><li><strong><code>rolebox memory list</code> 显示 <code>No memory entries found.</code></strong> 多半是目录不对：换到含 <code>.rolebox/</code> 的项目根目录再执行。记忆跟随工作目录，不跟随角色目录。</li><li><strong>写了 <code>low</code> 相关度的记忆，下个会话却看不到。</strong> 默认注入门槛是 <code>medium</code>；把它调低，或用 <code>memory_recall</code> 主动检索。</li><li><strong>以为重开会话就会忘记。</strong> 记忆在磁盘上的 SQLite 库里，与任何一次会话的生命周期无关。</li></ol><h2 id="你现在拥有什么" tabindex="-1">你现在拥有什么 <a class="header-anchor" href="#你现在拥有什么" aria-label="Permalink to &quot;你现在拥有什么&quot;">​</a></h2><ul><li>一个会「回顾会话 → 提炼决策 → 落盘」的角色（<code>memory</code> 函数）；</li><li>三个观察记忆库的入口：<code>rolebox memory list</code> / <code>stats</code> / <code>search</code>；</li><li>一套跨会话闭环：这次的决策，下次会话自动以 <code>&lt;available_memory&gt;</code> 出现在代理眼前。</li></ul><p>教程到这里结束。回头看你搭出的东西：角色、技能、引用文档、函数、子代理、带审批门与有界循环的图流水线，以及跨会话记忆。想继续深入，接着读<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>与<a href="/rolebox-docs/04-Advanced/memory-system.html">记忆系统</a>。</p>`,49)])])}const g=s(n,[["render",i]]);export{m as __pageData,g as default};
